"use client"

import * as React from "react"
import { Moon, Sun } from "lucide-react"
import { useTheme } from "next-themes"

export function ThemeToggle() {
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = React.useState(false)
  const toggleRef = React.useRef<HTMLButtonElement>(null)
  const isDragging = React.useRef(false)
  const hasMoved = React.useRef(false)
  const [{ x, y }, setPosition] = React.useState({ x: 0, y: 0 })
  const startPos = React.useRef({ x: 0, y: 0 })
  const pointerStart = React.useRef({ x: 0, y: 0 })

  React.useEffect(() => {
    setMounted(true)
    if (!theme) {
      setTheme('light');
    }
  }, [theme, setTheme])

  if (!mounted) {
    return <div className="fixed top-4 right-4 z-50 w-12 h-12" />
  }

  const isDark = theme === "dark"

  const handlePointerDown = (e: React.PointerEvent) => {
    isDragging.current = true;
    hasMoved.current = false;
    pointerStart.current = { x: e.clientX, y: e.clientY };
    startPos.current = { 
      x: e.clientX - x, 
      y: e.clientY - y 
    };
    if (toggleRef.current) {
      toggleRef.current.setPointerCapture(e.pointerId);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging.current) return;
    
    const moveDistance = Math.hypot(e.clientX - pointerStart.current.x, e.clientY - pointerStart.current.y);
    if (moveDistance > 5) {
      hasMoved.current = true;
    }

    if (hasMoved.current) {
      setPosition({
        x: e.clientX - startPos.current.x,
        y: e.clientY - startPos.current.y
      });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    isDragging.current = false;
    if (toggleRef.current) {
      toggleRef.current.releasePointerCapture(e.pointerId);
    }
    
    if (!hasMoved.current) {
      setTheme(isDark ? 'light' : 'dark');
    }
  };

  return (
    <button 
      ref={toggleRef}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      style={{ transform: `translate(${x}px, ${y}px)`, touchAction: 'none' }}
      className="fixed top-4 right-4 lg:top-6 lg:right-6 z-[60] flex items-center justify-center w-12 h-12 rounded-full bg-background/80 backdrop-blur-md border border-border shadow-md transition-colors hover:bg-background cursor-grab active:cursor-grabbing text-foreground"
      aria-label="Toggle theme"
    >
      {isDark ? <Moon className="h-5 w-5 transition-transform hover:scale-110" /> : <Sun className="h-5 w-5 transition-transform hover:scale-110" />}
    </button>
  )
}
